     "code": "def _cl(attrs, fds):\n    r = set(attrs)\n    ch = True\n    while ch:\n        ch = False\n        for l, rr in fds:\n            if set(l) <= r and not set(rr) <= r:\n                r |= set(rr)\n                ch = True\n    return r\n\nimport random\nfrom itertools import combinations\nrandom.seed(5)\nfor trial in range(25):\n    n = random.randint(3, 8)\n    R = set(\"ABCDEFGHIJ\"[:n])\n    fds = []\n    for _ in range(random.randint(1, 5)):\n        l = set(random.sample(sorted(R), random.randint(1, 2)))\n        r = set(random.sample(sorted(R), random.randint(1, 2)))\n        fds.append((l, r))\n    supers = [set(c) for k in range(n + 1) for c in combinations(sorted(R), k) if _cl(c, fds) >= R]\n    want = sorted(tuple(sorted(s)) for s in supers if not any(t < s for t in supers))\n    assert candidate_keys(R, fds) == want, (R, fds)\n"
