  {
   "id": "lock_manager",
   "title": "A lock manager",
   "prompt": "<p>Write a class <code>LockManager</code> for strict two-phase locking with shared (<code>\"S\"</code>) and exclusive (<code>\"X\"</code>) locks on named items. Each item has a set of holders and a first-in, first-out queue of waiting requests.</p>\n<ul><li><code>acquire(txn, item, mode)</code> returns <code>True</code> if the lock is granted now and <code>False</code> if the request is queued. A transaction that already holds the item in the same mode, or in X mode, gets <code>True</code> at once. A request is granted if it is compatible with every <em>other</em> holder (S with S only) and the item's queue is empty, so that a new reader can't overtake a waiting writer. An <em>upgrade</em> (a holder of S asking for X) is granted at once if the transaction is the only holder; otherwise it is queued. A granted upgrade replaces the S lock by X.</li>\n<li><code>release_all(txn)</code> releases all the transaction's locks and drops its queued requests (it has committed or aborted). Then, for each item in sorted order, it grants queued requests from the front of the queue as long as the front one is compatible with the current holders, stopping at the first that isn't. It returns the list of <code>(txn, item, mode)</code> granted, in the order granted.</li>\n<li><code>waits_for()</code> returns the set of edges <code>(waiter, other)</code>: a queued request waits for every other transaction that holds the item, or is queued ahead of it for the item, in a conflicting mode (two S modes don't conflict).</li>\n<li><code>deadlocked()</code> returns <code>True</code> if the wait-for graph has a cycle.</li></ul>\n<p>Assume a transaction that is waiting makes no further requests until its request is granted.</p>",
   "starter": "class LockManager:\n    def __init__(self):\n        pass\n\n    def acquire(self, txn, item, mode):\n        pass\n\n    def release_all(self, txn):\n        pass\n\n    def waits_for(self):\n        pass\n\n    def deadlocked(self):\n        pass\n",
   "hint": "<p>Store <code>self.holders[item]</code> as a dict from transaction to mode and <code>self.queue[item]</code> as a list of (txn, mode). Write one helper, <code>_ok(item, txn, mode)</code>, that checks compatibility with the other holders, and use it in both <code>acquire</code> and <code>release_all</code>. For <code>deadlocked</code>, run CS 201's depth-first search on the wait-for edges, looking for an edge back to a vertex still on the current path.</p>",
   "solution": "class LockManager:\n    def __init__(self):\n        self.holders = {}\n        self.queue = {}\n\n    def _ok(self, item, txn, mode):\n        others = [m for t, m in self.holders.get(item, {}).items() if t != txn]\n        return not others if mode == \"X\" else all(m == \"S\" for m in others)\n\n    def _grant(self, txn, item, mode):\n        self.holders.setdefault(item, {})[txn] = mode\n\n    def acquire(self, txn, item, mode):\n        held = self.holders.get(item, {}).get(txn)\n        if held == \"X\" or held == mode:\n            return True\n        q = self.queue.setdefault(item, [])\n        if held == \"S\" and mode == \"X\":\n            if self._ok(item, txn, \"X\"):\n                self._grant(txn, item, \"X\")\n                return True\n        elif not q and self._ok(item, txn, mode):\n            self._grant(txn, item, mode)\n            return True\n        q.append((txn, mode))\n        return False\n\n    def release_all(self, txn):\n        for h in self.holders.values():\n            h.pop(txn, None)\n        for item in self.queue:\n            self.queue[item] = [(t, m) for t, m in self.queue[item] if t != txn]\n        granted = []\n        for item in sorted(self.queue):\n            q = self.queue[item]\n            while q and self._ok(item, q[0][0], q[0][1]):\n                t, m = q.pop(0)\n                self._grant(t, item, m)\n                granted.append((t, item, m))\n        return granted\n\n    def waits_for(self):\n        edges = set()\n        for item, q in self.queue.items():\n            for i, (t, m) in enumerate(q):\n                for h, hm in self.holders.get(item, {}).items():\n                    if h != t and (m == \"X\" or hm == \"X\"):\n                        edges.add((t, h))\n                for u, um in q[:i]:\n                    if u != t and (m == \"X\" or um == \"X\"):\n                        edges.add((t, u))\n        return edges\n\n    def deadlocked(self):\n        graph = {}\n        for a, b in self.waits_for():\n            graph.setdefault(a, []).append(b)\n        state = {}\n        def dfs(u):\n            state[u] = 1\n            for v in graph.get(u, []):\n                if state.get(v) == 1 or (v not in state and dfs(v)):\n                    return True\n            state[u] = 2\n            return False\n        return any(u not in state and dfs(u) for u in list(graph))\n",
   "tests": [
    {
     "label": "Shared and exclusive locks",
     "type": "assert",
     "code": "lm = LockManager()\nassert lm.acquire(1, \"A\", \"S\") and lm.acquire(2, \"A\", \"S\"), \"two readers share\"\nassert lm.acquire(3, \"A\", \"X\") is False, \"a writer waits for readers\"\nassert lm.acquire(4, \"A\", \"S\") is False, \"a new reader doesn't overtake a waiting writer\"\nassert lm.acquire(1, \"A\", \"S\") is True, \"already held\"\nassert lm.waits_for() == {(3, 1), (3, 2), (4, 3)}, lm.waits_for()\nassert lm.release_all(1) == []\nassert lm.release_all(2) == [(3, \"A\", \"X\")]\nassert lm.release_all(3) == [(4, \"A\", \"S\")]\n"
    },
    {
     "label": "Granting several readers at once, in FIFO order",
     "type": "assert",
     "code": "lm = LockManager()\nassert lm.acquire(1, \"A\", \"X\")\nassert not lm.acquire(2, \"A\", \"S\") and not lm.acquire(3, \"A\", \"S\") and not lm.acquire(4, \"A\", \"X\") and not lm.acquire(5, \"A\", \"S\")\nassert lm.release_all(1) == [(2, \"A\", \"S\"), (3, \"A\", \"S\")], \"stop at the first incompatible request\"\nassert lm.waits_for() == {(4, 2), (4, 3), (5, 4)}\nassert not lm.deadlocked()\n"
    },
    {
     "label": "The upgrade deadlock",
     "type": "assert",
     "code": "lm = LockManager()\nassert lm.acquire(1, \"A\", \"S\") and lm.acquire(2, \"A\", \"S\")\nassert lm.acquire(1, \"A\", \"X\") is False and lm.acquire(2, \"A\", \"X\") is False\nassert lm.waits_for() == {(1, 2), (2, 1)} and lm.deadlocked()\nassert lm.release_all(2) == [(1, \"A\", \"X\")], \"the victim's abort lets T1 upgrade\"\nassert not lm.deadlocked() and lm.acquire(1, \"A\", \"S\") is True\nlm2 = LockManager()\nassert lm2.acquire(7, \"B\", \"S\") and lm2.acquire(7, \"B\", \"X\"), \"a sole holder upgrades at once\"\nassert lm2.acquire(8, \"B\", \"S\") is False\n"
    },
    {
     "label": "A deadlock across two items",
     "type": "assert",
     "code": "lm = LockManager()\nassert lm.acquire(1, \"A\", \"X\") and lm.acquire(2, \"B\", \"X\")\nassert not lm.acquire(1, \"B\", \"S\") and not lm.deadlocked()\nassert not lm.acquire(2, \"A\", \"S\") and lm.deadlocked()\nassert lm.release_all(1) == [(2, \"A\", \"S\")]\nassert not lm.deadlocked() and lm.waits_for() == set()\n"
    },
    {
     "label": "A three-way cycle and items granted in sorted order",
     "type": "assert",
     "hidden": true,
     "code": "lm = LockManager()\nfor t, x in [(1, \"C\"), (2, \"A\"), (3, \"B\")]:\n    assert lm.acquire(t, x, \"X\")\nassert not lm.acquire(1, \"A\", \"X\") and not lm.acquire(2, \"B\", \"X\")\nassert not lm.deadlocked()\nassert not lm.acquire(3, \"C\", \"S\") and lm.deadlocked()\nassert lm.release_all(2) == [(1, \"A\", \"X\")]\nlm = LockManager()\nassert lm.acquire(9, \"Z\", \"X\") and lm.acquire(9, \"M\", \"X\")\nassert not lm.acquire(5, \"Z\", \"S\") and not lm.acquire(6, \"M\", \"S\")\nassert lm.release_all(9) == [(6, \"M\", \"S\"), (5, \"Z\", \"S\")]\n"
    }
   ]
  }
